import{_ as d,a0 as s,w as i,s as u,ao as a,I as n,x as o,a1 as r,A as t}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const y=JSON.parse('{"title":"新手應知應會的Linux命令 | LCTT x X-CMD","titleTemplate":false,"description":"新手應知應會的Linux命令 | LCTT (201508) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"新手應知應會的Linux命令 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"新手應知應會的Linux命令 | LCTT (201508) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201508/20150730 Must-Know Linux Commands For New Users","title":"新手應知應會的Linux命令","tag":"201508","desc":""},"relativePath":"201508/20150730 Must-Know Linux Commands For New Users.md","filePath":"[post].md"}'),l={name:"201508/20150730 Must-Know Linux Commands For New Users.md"};function m(f,e,c,_,h,g){const p=s("Link");return i(),u("div",null,[e[16]||(e[16]=a(`<h1 id="新手應知應會的linux命令" tabindex="-1">新手應知應會的Linux命令 <a class="header-anchor" href="#新手應知應會的linux命令" aria-label="Permalink to “新手應知應會的Linux命令”">​</a></h1><p><img src="http://www.linux.com/images/stories/41373/fedora-cli.png" alt="Manage system updates via the command line with dnf on Fedora."></p><p><em>在Fedora上通過命令列使用dnf來管理系統更新</em></p><p>基於Linux的系統最美妙的一點，就是你可以在終端中使用命令列來管理整個系統。使用命令列的優勢在於，你可以使用相同的知識和技能來管理隨便哪個Linux發行版。</p><p>對於各個發行版以及桌面環境（DE）而言，要一致地使用圖形化用户界面（GUI）卻幾乎是不可能的，因為它們都提供了各自的用户界面。要明確的是，有些情況下在不同的發行版上需要使用不同的命令來執行某些特定的任務，但是，基本來説它們的思路和目的是一致的。</p><p>在本文中，我們打算討論Linux用户應當掌握的一些基本命令。我將給大家演示怎樣使用命令列來更新系統、管理軟件、操作文件以及切換到root，這些操作將在三個主要發行版上進行：Ubuntu（也包括其定製版和衍生版，還有Debian），openSUSE，以及Fedora。</p><p><em>讓我們開始吧！</em></p><h3 id="保持系統安全和最新" tabindex="-1">保持系統安全和最新 <a class="header-anchor" href="#保持系統安全和最新" aria-label="Permalink to “保持系統安全和最新”">​</a></h3><p>Linux是基於安全設計的，但事實上是，任何軟件都有缺陷，會導致安全漏洞。所以，保持你的系統更新到最新是十分重要的。這麼想吧：運行過時的操作系統，就像是你坐在全副武裝的坦克裏頭，而門卻沒有鎖。武器會保護你嗎？任何人都可以進入開放的大門，對你造成傷害。同樣，在你的系統中也有沒有打補丁的漏洞，這些漏洞會危害到你的系統。開源社區，不像專利世界，在漏洞補丁方面反應是相當快的，所以，如果你保持系統最新，你也獲得了安全保證。</p><p>留意新聞站點，瞭解安全漏洞。如果發現了一個漏洞，瞭解它，然後在補丁出來的第一時間更新。不管怎樣，在生產環境上，你每星期必須至少運行一次更新命令。如果你運行着一台複雜的服務器，那麼就要額外當心了。仔細閲讀變更日誌，以確保更新不會搞壞你的自定義服務。</p><p><strong>Ubuntu</strong>：牢記一點：你在升級系統或安裝不管什麼軟件之前，都必須要刷新倉庫（也就是repos）。在Ubuntu上，你可以使用下面的命令來更新系統，第一個命令用於刷新倉庫：</p><pre><code>sudo apt-get update
</code></pre><p>倉庫更新後，現在你可以運行系統更新命令了：</p><pre><code>sudo apt-get upgrade
</code></pre><p>然而，這個命令不會更新內核和其它一些包，所以你也必須要運行下面這個命令：</p><pre><code>sudo apt-get dist-upgrade
</code></pre><p><strong>openSUSE</strong>：如果你是在openSUSE上，你可以使用以下命令來更新系統（照例，第一個命令的意思是更新倉庫）：</p><pre><code>sudo zypper refresh
sudo zypper up
</code></pre><p><strong>Fedora</strong>：如果你是在Fedora上，你可以使用&#39;dnf&#39;命令，它是zypper和apt-get的&#39;同類&#39;：</p><pre><code>sudo dnf update
sudo dnf upgrade
</code></pre><h3 id="軟件安裝與移除" tabindex="-1">軟件安裝與移除 <a class="header-anchor" href="#軟件安裝與移除" aria-label="Permalink to “軟件安裝與移除”">​</a></h3><p>你只可以安裝那些你係統上啓用的倉庫中可用的包，各個發行版默認都附帶有並啓用了一些官方或者第三方倉庫。</p><p><strong>Ubuntu</strong>：要在Ubuntu上安裝包，首先更新倉庫，然後使用下面的語句：</p><pre><code>sudo apt-get install [package_name]
</code></pre><p>樣例：</p><pre><code>sudo apt-get install gimp
</code></pre><p><strong>openSUSE</strong>：命令是這樣的：</p><pre><code>sudo zypper install [package_name]
</code></pre><p><strong>Fedora</strong>：Fedora已經丟棄了&#39;yum&#39;，現在換成了&#39;dnf&#39;，所以命令是這樣的：</p><pre><code>sudo dnf install [package_name]
</code></pre><p>移除軟件的過程也一樣，只要把&#39;install&#39;改成&#39;remove&#39;。</p><p><strong>Ubuntu</strong>：</p><pre><code>sudo apt-get remove [package_name]
</code></pre><p><strong>openSUSE</strong>：</p><pre><code>sudo zypper remove [package_name]
</code></pre><p><strong>Fedora</strong>：</p><pre><code>sudo dnf remove [package_name]
</code></pre><h3 id="如何管理第三方軟件" tabindex="-1">如何管理第三方軟件？ <a class="header-anchor" href="#如何管理第三方軟件" aria-label="Permalink to “如何管理第三方軟件？”">​</a></h3><p>在一個龐大的開發者社區中，這些開發者們為用户提供了許多的軟件。不同的發行版有不同的機制來將這些第三方軟件提供給用户。當然，同時也取決於開發者怎樣將這些軟件提供給用户，有些開發者會提供二進制包，而另外一些開發者則將軟件發佈到倉庫中。</p><p>Ubuntu很多地方都用到PPA（個人包歸檔），但是，不幸的是，它卻沒有提供一個內建工具來幫助用於搜索這些PPA倉庫。在安裝軟件前，你將需要通過Google搜索PPA，然後手工添加該倉庫。下面就是添加PPA到系統的方法：</p><pre><code>sudo add-apt-repository ppa:&lt;repository-name&gt;
</code></pre><p>樣例：比如説，我想要添加LibreOffice PPA到我的系統中。我應該Google該PPA，然後從Launchpad獲得該倉庫的名稱，在本例中它是&quot;libreoffice/ppa&quot;。然後，使用下面的命令來添加該PPA：</p><pre><code>sudo add-apt-repository ppa:libreoffice/ppa
</code></pre><p>它會要你按下回車鍵來導入密鑰。完成後，使用&#39;update&#39;命令來刷新倉庫，然後安裝該包。</p><p>openSUSE擁有一個針對第三方應用的優雅的解決方案。你可以訪問software.opensuse.org，一鍵點擊搜索並安裝相應包，它會自動將對應的倉庫添加到你的系統中。如果你想要手工添加倉庫，可以使用該命令：</p><pre><code>sudo zypper ar -f url_of_the_repo name_of_repo
sudo zypper ar -f http://download.opensuse.org/repositories/LibreOffice:Factory/openSUSE_13.2/LibreOffice:Factory.repo LOF
</code></pre><p>然後，刷新倉庫並安裝軟件：</p><pre><code>sudo zypper refresh
sudo zypper install libreoffice
</code></pre><p>Fedora用户只需要添加RPMFusion（包括自由軟件和非自由軟件倉庫），該倉庫包含了大量的應用。如果你需要添加該倉庫，命令如下：</p><pre><code>dnf config-manager --add-repo http://www.example.com/example.repo
</code></pre><h3 id="一些基本命令" tabindex="-1">一些基本命令 <a class="header-anchor" href="#一些基本命令" aria-label="Permalink to “一些基本命令”">​</a></h3>`,51)),n("p",null,[e[1]||(e[1]=o("我已經寫了一些關於使用CLI來管理你係統上的文件的",-1)),r(p,{href:"http://www.linux.com/learn/tutorials/828027-how-to-manage-your-files-from-the-command-line"},{default:t(()=>[...e[0]||(e[0]=[o("文章",-1)])]),_:1}),e[2]||(e[2]=o("，下面介紹一些基本命令，這些命令在所有發行版上都經常會用到。",-1))]),e[17]||(e[17]=a(`<p>拷貝文件或目錄到一個新的位置：</p><pre><code>cp path_of_file_1 path_of_the_directory_where_you_want_to_copy/
</code></pre><p>將某個目錄中的所有文件拷貝到一個新的位置（注意斜線和星號，它指的是該目錄下的所有文件）：</p><pre><code>cp path_of_files/* path_of_the_directory_where_you_want_to_copy/
</code></pre><p>將一個文件從某個位置移動到另一個位置（尾斜槓是説放在該目錄中）：</p><pre><code>mv path_of_file_1 path_of_the_directory_where_you_want_to_move/
</code></pre><p>將所有文件從一個位置移動到另一個位置：</p><pre><code>mv path_of_directory_where_files_are/* path_of_the_directory_where_you_want_to_move/
</code></pre><p>刪除一個文件：</p><pre><code>rm path_of_file
</code></pre><p>刪除一個目錄：</p><pre><code>rm -r path_of_directory
</code></pre><p>移除目錄中所有內容，完整保留目錄文件夾：</p><pre><code>rm -r path_of_directory/*
</code></pre><h3 id="創建新目錄" tabindex="-1">創建新目錄 <a class="header-anchor" href="#創建新目錄" aria-label="Permalink to “創建新目錄”">​</a></h3><p>要創建一個新目錄，首先進入到你要創建該目錄的位置。比如説，你想要在你的Documents目錄中創建一個名為&#39;foundation&#39;的文件夾。讓我們使用 cd （即change directory，改變目錄）命令來改變目錄：</p><pre><code>cd /home/swapnil/Documents
</code></pre><p>（替換&#39;swapnil&#39;為你係統中的用户名）</p><p>然後，使用 mkdir 命令來創建該目錄：</p><pre><code>mkdir foundation
</code></pre><p>你也可以從任何地方創建一個目錄，通過指定該目錄的路徑即可。例如：</p><pre><code>mdkir /home/swapnil/Documents/foundation
</code></pre><p>如果你想要連父目錄一起創建，那麼可以使用 -p 選項。它會在指定路徑中創建所有目錄：</p><pre><code>mdkir -p /home/swapnil/Documents/linux/foundation
</code></pre><h3 id="成為root" tabindex="-1">成為root <a class="header-anchor" href="#成為root" aria-label="Permalink to “成為root”">​</a></h3><p>你或許需要成為root，或者具有sudo權力的用户，來實施一些管理任務，如管理軟件包或者對根目錄或其下的文件進行一些修改。其中一個例子就是編輯&#39;fstab&#39;文件，該文件記錄了掛載的硬盤驅動器。它在&#39;etc&#39;目錄中，而該目錄又在根目錄中，你只能作為超級用户來修改該文件。在大多數的發行版中，你可以通過&#39;su&#39;來成為root。比如説，在openSUSE上，我想要成為root，因為我要在根目錄中工作，你可以使用下面的命令之一：</p><pre><code>sudo su -
</code></pre><p>或</p><pre><code>su -
</code></pre><p>該命令會要求輸入密碼，然後你就具有root特權了。記住一點：千萬不要以root用户來運行系統，除非你知道你正在做什麼。另外重要的一點需要注意的是，你以root什麼對目錄或文件進行修改後，會將它們的擁有關係從該用户或特定的服務改變為root。你必須恢復這些文件的擁有關係，否則該服務或用户就不能訪問或寫入到那些文件。要改變用户，命令如下：</p><pre><code>sudo chown -R 用户:組 文件或目錄名
</code></pre><p>當你將其它發行版上的分區掛載到系統中時，你可能經常需要該操作。當你試着訪問這些分區上的文件時，你可能會碰到權限拒絕錯誤，你只需要改變這些分區的擁有關係就可以訪問它們了。需要額外當心的是，不要改變根目錄的權限或者擁有關係。</p><p>這些就是Linux新手們需要的基本命令。如果你有任何問題，或者如果你想要我們涵蓋一個特定的話題，請在下面的評論中告訴我們吧。</p><hr>`,34)),n("p",null,[e[4]||(e[4]=o("via: ",-1)),r(p,{href:"http://www.linux.com/learn/tutorials/842251-must-know-linux-commands-for-new-users"},{default:t(()=>[...e[3]||(e[3]=[o("http://www.linux.com/learn/tutorials/842251-must-know-linux-commands-for-new-users",-1)])]),_:1})]),n("p",null,[e[8]||(e[8]=o("作者：",-1)),r(p,{href:"http://www.linux.com/community/forums/person/61003"},{default:t(()=>[...e[5]||(e[5]=[o("Swapnil Bhartiya",-1)])]),_:1}),e[9]||(e[9]=o(" 譯者：",-1)),r(p,{href:"https://github.com/GOLinux"},{default:t(()=>[...e[6]||(e[6]=[o("GOLinux",-1)])]),_:1}),e[10]||(e[10]=o(" 校對：",-1)),r(p,{href:"https://github.com/wxy"},{default:t(()=>[...e[7]||(e[7]=[o("wxy",-1)])]),_:1})]),n("p",null,[e[13]||(e[13]=o("本文由 ",-1)),r(p,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...e[11]||(e[11]=[o("LCTT",-1)])]),_:1}),e[14]||(e[14]=o(" 原創翻譯，",-1)),r(p,{href:"https://linux.cn/"},{default:t(()=>[...e[12]||(e[12]=[o("Linux中國",-1)])]),_:1}),e[15]||(e[15]=o(" 榮譽推出",-1))])])}const L=d(l,[["render",m]]);export{y as __pageData,L as default};
